            print("DEV_LAUNCHER_VISIBLE")
            let row = app.buttons.matching(NSPredicate(format: "label CONTAINS 'localhost:8081'")).firstMatch
            if row.waitForExistence(timeout: 5) {
                row.tap()
            } else {
                let st = app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'localhost:8081'")).firstMatch
                if st.exists {
                    st.tap()
                } else {
                    app.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.40)).tap()
                }
            }
            Thread.sleep(forTimeInterval: 5)
        }

        let feedMarker = app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'whiskers'")).firstMatch
        let composerInput = app.textViews.firstMatch
        var ready = false
        for _ in 0..<40 {
            if composerInput.exists || feedMarker.exists {
                ready = true
                break
            }
            Thread.sleep(forTimeInterval: 1)
        }
        print("READY: \(ready)")
        dump(app, "LOADED")

        if !composerInput.exists {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.845, dy: 0.82)).tap()
            Thread.sleep(forTimeInterval: 3)
        }

        dump(app, "COMPOSER")

        let tv = app.textViews.firstMatch
        if tv.exists {
            let current = (tv.value as? String) ?? ""
            if !current.contains("silverbench") {
                tv.tap()
                Thread.sleep(forTimeInterval: 1)
                tv.typeText("testing hashtags #silverbench")
                Thread.sleep(forTimeInterval: 1)
            }
            dump(app, "TYPED")

            let post = app.buttons["Post"]
            if post.waitForExistence(timeout: 5) {
                post.tap()
            } else {
                app.coordinate(withNormalizedOffset: CGVector(dx: 0.925, dy: 0.085)).tap()
            }
            Thread.sleep(forTimeInterval: 6)
            dump(app, "POSTED")
        }
    }
}
